theme.css:
/* theme: Market Rebound | A storm of cyber breaches and geopolitical tensions meets a powerful market surge — a day of sharp contrasts on a green-and-red page. */
/* mood: bad */
/* layout: hero=classic; major-events=banner/grid-2; political-news=numbered/stack; financial-news=stat/grid-3; tech-news=outline/grid-2; entertainment-news=plain/stack; sports=split/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=tile/grid-2 */

.diary-page {
  --paper: #1c0b0d;
  --paper-alt: #291012;
  --ink: #f5e6e8;
  --ink-soft: #d4b4b8;
  --muted: #a3767c;
  --accent: #ff5c5c;
  --accent-ink: #1a0506;
  --rule: #4a1a1f;
  --font-display: var(--ff-bebas), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
}

.diary-page .diary-hero {
  background: linear-gradient(135deg, var(--paper-alt) 0%, var(--paper) 100%);
  border-bottom: 3px solid var(--accent);
  position: relative;
}

.diary-page .diary-hero::after {
  content: "▲";
  position: absolute;
  right: 2rem;
  bottom: 1rem;
  font-size: 3rem;
  color: var(--accent);
  opacity: 0.3;
  font-family: var(--font-ui);
}

.diary-page .diary-crumbs a {
  color: var(--accent);
  font-weight: 600;
}

.diary-page .diary-kicker {
  letter-spacing: 0.3em;
  font-size: 0.7rem;
  color: var(--accent);
  text-transform: uppercase;
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.75rem, 8vw, 6rem);
  letter-spacing: 0.05em;
  line-height: 0.9;
  color: var(--ink);
  text-shadow: 0 2px 0 var(--accent);
}

.diary-page .diary-summary {
  font-size: 1.3rem;
  line-height: 1.6;
  color: var(--ink-soft);
  border-left: 4px solid var(--accent);
  padding-left: 1.25rem;
}

.diary-page .diary-theme-note {
  color: var(--muted);
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 700;
  letter-spacing: 0.08em;
}

.diary-page .diary-toc {
  background: var(--paper);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-bottom:hover {
  color: var(--ink);
}

.diary-page .diary-toc-link.is-active {
  color: var(--accent);
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-section-head {
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.5rem;
}

.diary-page .diary-section-number {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.2em;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  color: var(--ink);
  letter-spacing: 0.04em;
}

.diary-page .diary-prose {
  font-size: 1.1rem;
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-card--banner .diary-card-inner {
  border: 2px solid var(--accent);
  border-radius: 0;
  box-shadow: 8px 8px 0 var(--accent);
}

.diary-page .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-display);
  letter-spacing: 0.03em;
  font-size: 1.3rem;
  padding: 1rem 1.25rem 0.8rem;
}

.diary-page .diary-card--banner .diary-card-body {
  padding: 1.25rem;
  background: var(--paper-alt);
}

.diary-page .diary-card--numbered .diary-card-inner {
  border-left: 4px solid var(--accent);
  padding-left: 1rem;
}

.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-size: 3.5rem;
  color: var(--accent);
}

.diary-page .diary-card--stat .diary-card-inner {
  border-top: 4px solid var(--accent);
  padding-top: 1.25rem;
}

.diary-page .diary-card-figure {
  font-family: var(--font-display);
  color: var(--accent);
  font-size: clamp(2.5rem, 14cqi, 4rem);
  letter-spacing: 0.02em;
}

.diary-page .diary-card--outline .diary-card-inner {
  border: 2px solid var(--rule);
  background: var(--paper-alt);
  border-radius: 0;
}

.diary-page .diary-card--plain {
  border-left: 3px solid var(--accent);
  padding-left: 1rem;
}

.diary-page .diary-card--split .diary-card-inner {
  border-top: 3px solid var(--accent);
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  background: var(--rule);
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 2px solid var(--rule);
  border-radius: 0;
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  color: var(--ink);
  letter-spacing: 0.04em;
}

.diary-page .diary-card-lede {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--paper);
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-card--banner .diary-card-thread {
  background: var(--paper-alt);
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark.is-up {
  color: var(--accent);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-footer {
  border-top-color: var(--rule);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

.diary-page .diary-footer-meta {
  color: var(--muted);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    margin-top: 3rem;
  }

  .diary-page .diary-toc-list {
    border-left: 1px solid var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

@media (prefers-reduced-motion: no-preference) {
  .diary-page .diary-hero-inner {
    animation: diary-rebound 0.6s ease-out;
  }

  @keyframes diary-rebound {
    from {
      opacity: 0;
      transform: translateY(-8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}
